// Lossless JSON interning for completed draws. The same award occurs in a roll
// and its winner's breakdown; repeated keys, addresses and records otherwise
// push large draws beyond the presentation cache's one-megabyte budget.
export function packJackpotCache(value) {
  const strings = [], nodes = [], stringIds = new Map(), nodeIds = new Map();
  const stringId = text => {
    if (!stringIds.has(text)) { stringIds.set(text, strings.length); strings.push(text); }
    return stringIds.get(text);
  };
  const encode = item => {
    if (typeof item === 'string') return [0, stringId(item)];
    if (item == null || typeof item !== 'object') return item;
    const node = Array.isArray(item)
      ? [0, ...item.map(encode)]
      : [1, ...Object.entries(item).flatMap(([name, child]) => [stringId(name), encode(child)])];
    const signature = JSON.stringify(node);
    if (!nodeIds.has(signature)) { nodeIds.set(signature, nodes.length); nodes.push(node); }
    return [1, nodeIds.get(signature)];
  };
  const root = encode(value);
  return { encoding: 'interned-json-v1', strings, nodes, root };
}

export function unpackJackpotCache(value) {
  if (value?.encoding !== 'interned-json-v1') return value;
  const { strings, nodes, root } = value;
  if (!Array.isArray(strings) || !strings.every(item => typeof item === 'string') || !Array.isArray(nodes)) {
    throw new Error('Invalid jackpot cache dictionary');
  }
  const decoded = new Map();
  const index = (value, length) => Number.isSafeInteger(value) && value >= 0 && value < length;
  const decode = (token, before = nodes.length) => {
    if (!Array.isArray(token)) {
      if (token == null || typeof token === 'boolean' || typeof token === 'number') return token;
      throw new Error('Invalid jackpot cache value');
    }
    if (token.length !== 2) throw new Error('Invalid jackpot cache reference');
    const [type, id] = token;
    if (type === 0 && index(id, strings.length)) return strings[id];
    // Encoded children always precede their parent. Reject forward/circular
    // references even when local storage contains malformed data.
    if (type !== 1 || !index(id, before)) throw new Error('Invalid jackpot cache node');
    if (decoded.has(id)) return decoded.get(id);
    const node = nodes[id];
    if (!Array.isArray(node)) throw new Error('Invalid jackpot cache node');
    let result;
    if (node[0] === 0) result = node.slice(1).map(child => decode(child, id));
    else if (node[0] === 1 && node.length % 2 === 1) {
      const pairs = [];
      for (let i = 1; i < node.length; i += 2) {
        if (!index(node[i], strings.length)) throw new Error('Invalid jackpot cache key');
        pairs.push([strings[node[i]], decode(node[i + 1], id)]);
      }
      result = Object.fromEntries(pairs);
    } else throw new Error('Invalid jackpot cache node');
    decoded.set(id, result);
    return result;
  };
  // JSON storage does not preserve shared object identity. Materialize each
  // occurrence so mutating one day's empty player-trait map cannot change a
  // different day whose identical map used the same dictionary entry.
  return JSON.parse(JSON.stringify(decode(root)));
}
